import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() {
            if (ptr >= len) {
                try {
                    len = in.read(buffer);
                    ptr = 0;
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= ' ' && c != -1) {
                c = read();
            }
            if (c == -1) return -1;
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        if (n == -1) return;

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int[] left = new int[n];
        final int INF = 1_000_000_000;

        int current = INF;
        for (int i = 0; i < n; i++) {
            if (current < INF) {
                current++;
            }
            if (a[i] != -1) {
                current = Math.min(current, a[i]);
            }
            left[i] = current;
        }

        int[] right = new int[n];
        current = INF;
        for (int i = n - 1; i >= 0; i--) {
            if (current < INF) {
                current++;
            }
            if (a[i] != -1) {
                current = Math.min(current, a[i]);
            }
            right[i] = current;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int ans = Math.min(left[i], right[i]);
            sb.append(ans);
            if (i < n - 1) {
                sb.append(' ');
            }
        }
        sb.append('\n');
        System.out.print(sb.toString());
    }
}
